  function individualTip(age, id) {
    var topic = topics[id];
    if (age === 'preschool') return 'С родителем можно обсудить ' + topic + '. Участие в полном курсе уточним отдельно.';
    if (age === '6-8') return 'С взрослым можно придумать ' + topic + ' и изобразить идею; формат курса уточним отдельно.';
    if (age === '9-12') return 'Продумать ' + topic + ', разделить задачу на шаги и обсудить её с наставником.';
    if (age === '13-17') return 'Продумать ' + topic + ' и способ проверить идею; правила сервисов обсудить со взрослым.';
    if (age === 'adult') return 'Продумать ' + topic + ' и обсудить следующий шаг с учётом опыта.';
    return 'Первый шаг, его объём и поддержку обсудим с наставником.';
  }
